<script setup>
import useModelConfig from '../useModelConfig'
import Markdown from '@/views/chat/components/Markdown.vue'
import { getEmbedModels } from '@/services/knowledge'
import Dialog from 'primevue/dialog'

const isdialog = ref(false)

const ishavingembedding = ref(0)

const props = defineProps({
  modelId: {
    type: [Number, String],
    default: ''
  },
  model: {
    type: Object,
    default: () => ({})
  },
  currentUrl: {
    type: String,
    default: ''
  }
})

const { url, save, loading } = useModelConfig(props)

watch(
  () => props.currentUrl,
  (value) => {
    url.value = value
  },
  {}
)

function confirmEmbedding() {
  getEmbedModels().then((res) => {
    let modelList = res.resData
    isdialog.value = true
    if (modelList === null) {
      ishavingembedding.value = 2
    } else {
      if (modelList.length) {
        ishavingembedding.value = 1
        save()
      } else {
        ishavingembedding.value = 2
      }
    }
  })
}

const windowsOllamaConfig = `
  ### 推荐下载模型
\`\`\`bash
  ollama pull nomic-embed-text
\`\`\`
  ### ollama安装流程

 请参照对话模型中Ollama方式安装配置

  ### 其他Embedding模型推荐
\`\`\`bash
ollama pull mxbai-embed-large
ollama pull snowflake-arctic-embed
ollama pull granite-embedding
\`\`\`
  `
const isHaveEmbedding = `
 您的OllamaUrl中包含嵌入模型，可直接使用
`
const isnotHaveEmbedding = `
 您的OllamaUrl中不包含嵌入模型，请根据下面教程进行部署
`
</script>

<template>
  <div class="flex flex-col items-start justify-start gap-4 p-4 p-4 bg-surface-50 dark:bg-surface-900">
    <div class="">
      <span>检测本地Ollama中是否包含嵌入模型</span>
    </div>
    <InputText
      variant="filled"
      :pt="{
        input: {
          style: {
            width: '100%',
            backgroundColor: '#e9ecef',
            color: '#6c757d'
          }
        }
      }"
      class="w-full"
      v-model="url"
      placeholder="http://localhost:11434"
      :disabled="true"
    />
    <!-- <Button severity="contrast" label="保存" @click="save" :loading="loading"></Button> -->
    <Button severity="contrast" label="检测" @click="confirmEmbedding" :loading="loading"></Button>
    <Dialog v-model:visible="isdialog" header="本地嵌入模型检测" :style="{ width: '800px' }" :modal="true">
      <div class="content-box" v-if="ishavingembedding === 1">
        <Markdown :content="isHaveEmbedding"></Markdown>
      </div>
      <div class="content-box" v-if="ishavingembedding === 2">
        <Markdown :content="isnotHaveEmbedding"></Markdown>
      </div>
    </Dialog>
    <Markdown :content="windowsOllamaConfig"></Markdown>
  </div>
</template>

<style scoped lang="scss">
.password {
  :deep(.p-password-input) {
    width: 100%;
  }
}
</style>
